// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf',
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2015, "2-3", [{"author":"Е. Ренковская","question":"В какой из этих пар слова связаны между собой по смыслу не так, как в остальных?","choices":["<em>слепой</em> — <em>слепец</em>","<em>глупый</em> — <em>глупец</em>","<em>немой</em> — <em>немец</em>","<em>старый</em> — <em>старец</em>","<em>хитрый</em> — <em>хитрец</em>."],"key":"В","review":["Похожие пары слов","Прочитай «слепец — слепой человек», «глупец — глупый человек», «старец — старый человек» и «хитрец — хитрый человек». У каждого признака нашлось название человека, которому он свойствен.","«Немец» означает человека, принадлежащего к немецкому народу. Слово ничего не сообщает о его способности говорить. По смыслу пара «немой — немец» устроена иначе."]},{"author":"Т. Заболотская","question":"Во фразе <em>Дай немножко творога</em> «спрятался» кот. Какая рыба «спряталась» в двустишии?\n<em>Здесь поплаваю немножко,</em>\n<em>Погляжу, вкусна ли мошка</em>.","choices":["<em>карась</em>","<em>окунь</em>","<em>плотва</em>","<em>судак</em>","<em>налим</em>."],"key":"Д","review":["Рыба в двустишии","В «немножко творога» слово «кот» собрано из последних букв «немножко» и первой буквы «творога». Ищи рыбу на границах слов таким же способом.","Возьми «на» из «вкусна», целиком «ли» и первую «м» из «мошка». Получится «налим»."]},{"author":"И. Рубанов","question":"Мышастый конь — это какой?","choices":["серый","рыжий","чёрный","жёлтый","красный."],"key":"А","review":["Мышастый конь","В слове «мышастый» слышно «мышь». Вспомни обычный цвет мышиной шерсти.","Мышь серая. Мышастым называют коня примерно такого же серого цвета."]},{"author":"К. Гилярова","question":"Из какого слова нельзя получить другое слово, добавив гласную букву в начале?","choices":["<em>лень</em>","<em>кол</em>","<em>стул</em>","<em>кран</em>","<em>корь.</em>"],"key":"В","review":["Гласная перед словом","Добавь «о» к «лень», «у» к «кол», «э» к «кран» и «я» к «корь». Получатся «олень», «укол», «экран», «якорь».","У «стул» перебор гласных перед с не даёт знакомого слова. Поэтому оно единственное осталось без пары."]},{"author":"Н. Добрушина","question":"Ляля и папа бодаются и мычат. Папа говорит: «Мы быки». Ляля говорит:\n«Нет, мы мыки». Папа отвечает: «Тогда я ― як». Ляля говорит: «Нет, ты ― …».","choices":["бык","тык","вык","рык","мук."],"key":"Б","review":["Игра Ляли с папой","В «мы быки» Ляля переносит начало «мы» в следующее слово. «Быки» заменяются на «мыки», а конец «ки» остаётся.","Чтобы переделать «як» вслед за словом «ты», замени начало «я» на «ты». Сохрани конечное к и получи «тык»."]},{"author":"Е. Муравенко","question":"В каком из ответов слово <em>вишнёвый</em> означает не то, что в остальных?","choices":["<em>вишнёвый компот</em>","<em>вишнёвая косточка</em>","<em>вишнёвая футболка</em>","<em>вишнёвое варенье</em>","<em>вишнёвый йогурт</em>."],"key":"В","review":["Вишнёвое в пяти ответах","Компот, варенье и йогурт могут содержать вишню, а вишнёвая косточка находится внутри плода.","Футболка может быть цвета спелой вишни. «Вишнёвая» здесь обозначает тёмно-красный цвет."]},{"author":"И. Иткин","question":"<em>Люблю</em> — <em>обожаю</em>, <em>не</em> <em>люблю</em> — <em>терпеть</em> <em>не</em> <em>могу</em>, <em>не</em> <em>разбираюсь</em> — <em>ни</em> <em>бум</em>-<em>бум</em>, <em>не</em> <em>знаю</em> — ...","choices":["<em>знаю</em>","<em>догадываюсь</em>","<em>сомневаюсь</em>","<em>понятия</em> <em>не</em> <em>имею</em>","<em>хочу</em> <em>всё</em> <em>знать</em>."],"key":"Г","review":["Как сказать сильнее","В каждой паре второе выражение усиливает первое. «Обожаю» сильнее, чем «люблю», а «ни бум-бум» означает «совсем не разбираюсь».","«Понятия не имею» значит «совсем не знаю». Это выражение продолжает ряд."]},{"author":"И. Рубанов","question":"<em>Мальчишка полез через забор в сад. «____, ты куда?»</em> — <em>окликнул его</em> <em>хозяин</em>. Какое слово лучше всего поставить вместо прочерка?","choices":["<em>Ай</em>","<em>Ой</em>","<em>Уй</em>","<em>Эй</em>","<em>Эх</em>."],"key":"Г","review":["Оклик из сада","Хозяин увидел мальчика и хочет, чтобы тот обратил на него внимание. Ищи междометие для оклика.","«Эй!» произносят, чтобы привлечь внимание. «Ой!» и «ай!» обычно выражают удивление, испуг или боль."]},{"author":"Б. Иомдин","question":"Какое слово не может быть ответом на вопрос «сколько»?","choices":["<em>раз</em>","<em>два</em>","<em>три</em>","<em>четыре</em>","<em>пять.</em>"],"key":"А","review":["Ответ на «сколько?»","Подставь варианты в ответ на вопрос «Сколько яблок?» Можно сказать «два», «три», «четыре» или «пять».","«Раз» обычно называет повторение действия, например в «пять раз». Самостоятельно вместо числа оно звучит в специальных случаях, например при счёте «раз, два, три»."]},{"author":"Б. Иомдин","question":"<em>— Что же можно сварить побыстрей? Ответ простой и ясный:</em> <em>бульон! Папа даже руки _______</em> (Виктор Драгунский, Денискины рассказы)<em>.</em> Каким словом заканчивается эта фраза?","choices":["<em>потерел</em>","<em>потерил</em>","<em>потрил</em>","<em>потёрл</em>","<em>потёр.</em>"],"key":"Д","review":["Папа и бульон","Вспомни жест, когда от радости трут ладони. В предложении нужен глагол «потереть» в прошедшем времени.","Скажи «я потёр руки» или «папа потёр руки». В мужской форме «потёр» пишется ё, а л на конце нет."]},{"author":"М. Рубинштейн","question":"Пересказывая сказку Дины Сабитовой «Цирк в шкатулке», Маша сначала запуталась в нескольких именах цирковой лошади, но потом поняла, в каком порядке шли её имена, и вспомнила, что лошадь звали ...","choices":["Ида Амелия Эва Казимира Дина","Беатриса Аделаида Гортензия Виолетта Душка","Дина Амелия Ида Эва Казимира","Аделаида Беатриса Виолетта Гортензия Душка","Душка Гортензия Аделаида Виолетта."],"key":"Г","review":["Имена цирковой лошади","В каждом варианте посмотри на первые буквы имён. Среди них должны по порядку встретиться начала соседних букв алфавита.","Аделаида, Беатриса, Виолетта, Гортензия, Душка дают А, Б, В, Г, Д. Только этот вариант сохраняет такой порядок."]},{"author":"Б. Иомдин","question":"Какое слово обычно относится <strong>не</strong> к человеку?","choices":["<em>бегун</em>","<em>прыгун</em>","<em>скакун</em>","<em>плясун</em>","<em>шалун.</em>"],"key":"В","review":["Кто как двигается","Бегун бегает, прыгун прыгает, плясун пляшет, шалун шалит. Эти слова обычно называют людей.","«Скакун» в обычной речи — быстрая лошадь, например участник скачек. Поэтому это слово подходит."]},{"author":"Л. Фёдорова","question":"<em>А заяц ___ как ___</em>.\nКакое слово мы два раза пропустили в этом предложении?","choices":["<em>вот</em>","<em>раз</em>","<em>нет</em>","<em>там</em>","<em>тут</em>."],"key":"Д","review":["Заяц появился","В обоих пропусках должно стоять одно и то же слово. Ищи устойчивый оборот о том, кто внезапно появился.","«Тут как тут» значит «сразу оказался рядом». Целиком выйдет «А заяц тут как тут»."]},{"author":"М. Рубинштейн и А. Пиперски","question":"Цветная встречается часто, а чёрно-белая — практически никогда. Что имеется в виду?","choices":["<em>фотография</em>","<em>капуста</em>","<em>редька</em>","<em>картинка</em>","<em>съёмка</em>."],"key":"Б","review":["Цветная и чёрно-белая","Фотография, картинка или съёмка могут быть цветными и чёрно-белыми. Редька бывает чёрной или белой, но «цветная редька» не привычное название.","«Цветная капуста» — известный вид капусты, даже если её соцветия белые. Сорта «чёрно-белая капуста» обычно не называют."]},{"author":"Е. Муравенко","question":"У гусёнка папа ― гусь, а мама ― гусыня. У кого ещё из детёнышей животных имена обоих родителей образованы от того же корня, что и его имя?","choices":["у утёнка","у цыплёнка","у телёнка","у ягнёнка","у козлёнка."],"key":"Д","review":["Названия родителей","Для каждого малыша назови обоих родителей. Например, у утёнка это утка и селезень, а у телёнка — корова и бык. Нужны три слова с общим корнем.","У козлёнка папа козёл, мама коза, и все названия начинаются с «коз-». У цыплёнка и ягнёнка названия родителей тоже различаются по корню."]},{"author":"А. Сомин","question":"Арабское слово <em>кытаар</em> имеет несколько значений. Одно из них — ‘вереница верблюдов’, а ещё одно —","choices":["‘карета’","‘паровоз’","‘пароход’","‘автобус’","‘поезд’."],"key":"Д","review":["Два смысла по-арабски","Вереница верблюдов вытянута в линию: животные идут одно за другим. Найди транспорт с таким же устройством.","У поезда один за другим идут вагоны. Поэтому арабское «кытаар» означает и караван, и поезд."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Какое словосочетание может иметь противоположные значения?","choices":["<em>ужасно обиженный</em>","<em>ужасно расстроенный</em>","<em>ужасно обрадованный</em>","<em>ужасно аккуратный</em>","<em>ужасно воспитанный</em>."],"key":"Д","review":["Два смысла «ужасно»","«Ужасно» бывает усилением, как «очень», или описанием плохого результата, как в «ужасно приготовленный обед».","«Ужасно воспитанный» может значить «очень воспитанный» и «воспитанный очень плохо». Чтобы различить смыслы, прислушайся к остальной фразе."]},{"author":"И. Иткин","question":"Какие буквы раньше (до 1918 года) назывались <em>еръ</em>, <em>ерь</em>, <em>еры́</em>?","choices":["<em>ъ</em>, <em>ы</em>, <em>ь</em>","<em>ъ</em>, <em>ь</em>, <em>ы</em>","<em>ь</em>, <em>ъ</em>, <em>ы</em>","<em>ы</em>, <em>ъ</em>, <em>ь</em>","<em>ы</em>, <em>ь</em>, <em>ъ</em>."],"key":"Б","review":["Старые имена букв","Посмотри на последние буквы старых названий. В «еръ» виден ъ, а в «ерь» — ь.","«Еры́» заканчивается на ы и было названием этой буквы. Порядок получается ъ, ь, ы."]},{"author":"Б. Иомдин","question":"<em>— Прошу не торопить меня, — сказал Иа-Иа, медленно поднимаясь.</em>\n<em>— Прошу не…</em> Закончите фразу Иа-Иа.","choices":["<em>данувайкать</em>","<em>кудавайнать</em>","<em>вадунайкать</em>","<em>нудавайкать</em>","<em>кадавайнуть</em>."],"key":"Г","review":["Иа-Иа просит подождать","Когда кого-то торопят, часто повторяют «ну давай!». Иа-Иа хочет, чтобы ему перестали говорить именно это.","Из всего выражения делают глагол «нудавайкать». Его конец «-кать» устроен так же, как в слове «ойкать»."]},{"author":"Б. Иомдин и Е. Муравенко","question":"Какая фраза выглядит странно?","choices":["<em>Листья пожелтели и начали вянуть.</em>","<em>Листья пожелтели, но опали.</em>","<em>Листья пожелтели и опали.</em>","<em>Листья пожелтели, но долго не опадали.</em>","<em>Листья пожелтели и начали опадать</em>."],"key":"Б","review":["Листья осенью","Союз «и» просто соединяет события. «Но» предупреждает, что дальше будет результат, которого мы не ждали.","После пожелтения листьев опадание ожидаемо, поэтому странно «пожелтели, но опали». «Но долго не опадали» годится, потому что задержка удивляет."]},{"author":"А. Иткин","question":"Что можно передать, но нельзя отдать?","choices":["деньги","честь","письмо","подарок","привет."],"key":"Д","review":["Что можно передать","Сравни сочетания с обоими глаголами. Можно передать и отдать деньги, письмо и подарок. Слово «честь» тоже можно поставить после «отдать», когда речь о воинском приветствии.","«Передать привет» значит сообщить, что кто-то просил поздороваться. Сочетание «отдать привет» обычно не употребляют."]},{"author":"И. Иткин","question":"<em>Ани Лорак</em> — сценическое имя известной украинской певицы. А её настоящее имя — ...","choices":["<em>Анна-Лора</em>","<em>Каролина</em>","<em>Карина</em>","<em>Алина</em>","<em>Лолита</em>."],"key":"Б","review":["Имя певицы","Соедини «Ани Лорак» в одну запись без пробела. Попробуй прочитать сценическое имя с конца.","Из «АНИЛОРАК» выходит «КАРОЛИНА». Так сценическое имя скрывает настоящее."]},{"author":"И. Иткин","question":"В каком из слов: <em>полвторого</em>, <em>полчетвёртого</em>, <em>полвосьмого</em> — два звука [в]?","choices":["<em>полвторого</em>","<em>полчетвёртого</em>","<em>полвосьмого</em>","во всех","ни в одном."],"key":"В","review":["Звуки в трёх словах","В конце всех трёх слов «-ого» буква г звучит как [в]. Для ответа нужно найти ещё один именно твёрдый [в].","В «полвторого» перед [т] слышно [ф], в «полчетвёртого» перед ё — мягкий [в’]. В «полвосьмого» перед о слышно твёрдое [в], поэтому их два."]},{"author":"Б. Иомдин","question":"Для чего предназначался щаной горшок?","choices":["для цветов","для каши","для супа","для туалета","для собак."],"key":"В","review":["Старый горшок","В слове «щаной» узнай название блюда, которое начинается на щ. Это щи, суп из капусты и других овощей.","Щаной горшок предназначался для щей. Среди вариантов подходит «для супа»."]},{"author":"И. Иткин и С. Переверзева","question":"В фантастическом романе Евгения Замятина «Мы» персонажи носят имена, состоящие из одной буквы и нескольких цифр. Герой, от лица которого ведётся повествование, воспринимает своего приятеля как «своё другое я». А как зовут этого приятеля?","choices":["P-13","Q-13","R-13","S-13","T-13."],"key":"В","review":["Буква в имени героя","Все номера одинаковы, поэтому работай с буквами P, Q, R, S, T. В выражении «другое я» ищи подсказку к форме буквы.","Латинская R похожа на зеркально отражённую русскую Я. Поэтому другое «я» героя — R-13."]},{"author":"Б. Иомдин","question":"<em>— Молчи, _____, —</em>\n<em>Сказала _____:</em>\n<em>В тебе _____ я,</em>\n<em>Во мне до _____ я.</em>\nВ этом стихотворении мы пропустили четыре слова. Два последних называют числа. А какова разность этих чисел?","choices":["60","71","82","93","104<em>.</em>"],"key":"Г","review":["Два числа в стихах","Соедини пропуски с «я». «Семь я» складывается в «семья», а «ста я» — в «стая». Эти же слова заполняют первые две строки.","После «до» число «сто» принимает форму «ста», поэтому числа равны 7 и 100. Вычти 7 из 100, получится 93."]},{"author":"А. Сомин","question":"Вот список слов на якутском языке, в котором два слова пропущены: ______, оптуорунньук, сэрэдэ, чэппиэр, бээтинсэ, ______, баскыhыанньа. Какое слово пропущено первым? (Буква h читается примерно как русское <em>х</em>.)","choices":["сыаналааhын","быраабыла","мэндиэмэн","бэнидиэльник","чоппууска."],"key":"Г","review":["Ряд якутских слов","Узнай русские слова в середине ряда. «Сэрэдэ», «чэппиэр», «бээтинсэ» напоминают среду, четверг и пятницу.","«Оптуорунньук» напоминает вторник, поэтому первым нужен понедельник. Среди вариантов на него похоже «бэнидиэльник»."]},{"author":"С. Переверзева","question":"<em>Джаз</em>, <em>лимон</em>, <em>непросто</em>, <em>чешущее</em>.\nКакое ещё слово можно отнести в этот список?","choices":["<em>ящичек</em>","<em>элемент</em>","<em>хочешь</em>","<em>клеймо</em>","<em>выгода</em>."],"key":"Д","review":["Буквы в четырёх словах","Пропусти гласные. Останутся ДЖЗ, ЛМН, НПРСТ, ЧШЩ. В каждом слове согласные идут подряд в алфавите, если и там пропускать гласные.","В «выгода» остаются ВГД, и это соседние согласные. Например, в «элемент» остаётся ЛМНТ, но между Н и Т пропущены П, Р, С."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
